    ('174488ca-afc4-5157-984c-e59610dde149'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France industrielle', 16, 'Dynamiques territoriales de la France contemporaine', 'geographie'),
    ('d0b9a0a7-1354-5e70-b8a7-ca9d337f0a05'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France agricole', 17, 'Dynamiques territoriales de la France contemporaine', 'geographie'),
    ('0cacb155-eb80-5424-8bdb-844960d264cd'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France des services', 18, 'Dynamiques territoriales de la France contemporaine', 'geographie'),
    ('2222b08d-0800-5557-8246-9c0ac13b4a44'::uuid, 'histoire-geo', '3e', 'Les espaces de faible densité', 19, 'Dynamiques territoriales de la France contemporaine', 'geographie'),
    ('9b55af5a-e29d-5cbb-87e7-2fc8d2f43360'::uuid, 'histoire-geo', '3e', 'L’aménagement comme réponse aux inégalités territoriales', 20, 'Pourquoi et comment aménager le territoire ?', 'geographie'),
    ('0d896e0b-f92e-567e-a3fb-6306c0b0b0ff'::uuid, 'histoire-geo', '3e', 'La politique de la ville', 21, 'Pourquoi et comment aménager le territoire ?', 'geographie'),
    ('5f5f3f5f-1797-5381-829b-8fda245c1ba1'::uuid, 'histoire-geo', '3e', 'Les territoires ultra-marins français', 22, 'Pourquoi et comment aménager le territoire ?', 'geographie'),
    ('470832dc-e0a6-54b4-b10d-8a22ce95e228'::uuid, 'histoire-geo', '3e', 'L’Union européenne : un territoire en construction', 23, 'La France et l’Union européenne', 'geographie'),
    ('b330d15a-2c67-5816-8f56-bca0736238c2'::uuid, 'histoire-geo', '3e', 'Les contrastes territoriaux à l’intérieur de l’Union européenne', 24, 'La France et l’Union européenne', 'geographie'),
    ('53f85f17-1b08-543a-8e26-c9b9568ded36'::uuid, 'histoire-geo', '3e', 'L’Europe dans le monde', 25, 'La France et l’Union européenne', 'geographie'),
    ('7d06202f-144f-56d7-a58b-526573dc5c78'::uuid, 'histoire-geo', '3e', 'La France dans l’Union européenne', 26, 'La France et l’Union européenne', 'geographie')
  ) AS v(id, slug, level, title, position, theme, discipline)
  JOIN public.subjects s ON s.slug = v.slug
-- ON CONFLICT NU : `chapters` porte aussi UNIQUE(subject_id, level, title).
ON CONFLICT DO NOTHING;

-- 1 bis. Axes du programme -------------------------------------------------
-- `chapters.theme` (migration 234) : l’intitulé du programme officiel qui
-- coiffe le chapitre. La page matière s’en sert pour grouper au lieu
-- d’aligner 28 lignes à plat. UPDATE et non INSERT : le chapitre peut déjà
-- exister (l’INSERT précédent l’aurait alors ignoré).
UPDATE public.chapters c SET theme = v.theme
