    ('d0b9a0a7-1354-5e70-b8a7-ca9d337f0a05'::uuid, 'Dynamiques territoriales de la France contemporaine'),
    ('0cacb155-eb80-5424-8bdb-844960d264cd'::uuid, 'Dynamiques territoriales de la France contemporaine'),
