    ('0d896e0b-f92e-567e-a3fb-6306c0b0b0ff'::uuid, 'Pourquoi et comment aménager le territoire ?'),
    ('5f5f3f5f-1797-5381-829b-8fda245c1ba1'::uuid, 'Pourquoi et comment aménager le territoire ?'),
